// Install registers this tatemono's compiled routes. Generated by the Go
// backend engine from the DSL build payload — do not edit by hand.
func Install(r chi.Router, svc modulespec.Services) {

	// Engine-owned auth routes are served dynamically by the fallback handler.
	r.Method(http.MethodGet, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))
	r.Method(http.MethodPost, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))
	r.Method(http.MethodDelete, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))

	modMessageController := modulespec.APIModule{Name: "broadcast-test", Table: "messages", Middleware: []string{}, SoftDeletes: false}
	specDestroy := modulespec.EndpointSpec{Operation: "destroy", Method: "DELETE", Path: "/api/broadcast-test/messages/{id}", Body: "", Type: "", ResponseType: "message", ResponseValue: "Message deleted"}
	r.Method("DELETE", "/api/broadcast-test/messages/{id}", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Remove(w, req, modMessageController, specDestroy) }))
	specIndex := modulespec.EndpointSpec{Operation: "index", Method: "GET", Path: "/api/broadcast-test/messages", Body: "", Type: "", ResponseType: "paginated", ResponseValue: "", Paginated: true}
	r.Method("GET", "/api/broadcast-test/messages", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.List(w, req, modMessageController, specIndex) }))
	specStore := modulespec.EndpointSpec{Operation: "store", Method: "POST", Path: "/api/broadcast-test/messages", Body: "", Type: "broadcast", ResponseType: "single", ResponseValue: "", Validation: map[string]string{"channel_type": "sometimes|string|max:50", "content": "required|string|max:500"}}
	r.Method("POST", "/api/broadcast-test/messages", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Custom(w, req, modMessageController, specStore) }))

	broadcastModule := modulespec.APIModule{Name: ModuleName, Table: "messages"}
	r.Method(http.MethodGet, "/api/"+ModuleName+"/sse-poll/{channelType}", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.BroadcastPoll(w, req, broadcastModule) }))
}
